def build_agent(sandbox):
    start_x = 4.5
    # Create main beam at starting position
    main_beam = sandbox.add_beam(start_x, 1.5, width=1.0, height=3.0, density=5.0)
    pads = []
    joints = []
    prev_b = main_beam

    # Create 3 beams vertically within build zone
    for i in range(3):
        y = 1.5 + i * 1.5
        if y > sandbox.BUILD_ZONE_Y_MAX:
            break
        b = sandbox.add_beam(start_x, y, width=1.0, height=3.0, density=5.0)
        # Add pad at the right end of each beam (x=5.0)
        pad = sandbox.add_pad(5.0, y, radius=0.12, density=0.8)
        pads.append(pad)
        # Connect with pivot joint at the top of the previous beam
        joint_anchor = (start_x, prev_b.position[1] + 1.5)
        joint = sandbox.add_joint(prev_b, b, joint_anchor, type='pivot', lower_limit=-math.pi, upper_limit=math.pi)
        joints.append(joint)
        prev_b = b

    # Initialize control parameters
    control = {
        'cycle': 20,          # Control cycle length
        'overlap': 10,        # Overlap time for pad activation
        'speed': 10.0,        # Motor speed
        'torque': 1000.0,     # Motor torque
        'p_torso': pads[:2],  # First two pads as torso
        'p_arm': pads[2:],    # Remaining pads as arms
        'joint': joints[0]    # Drive the first joint
    }
    return {'main_body': main_beam, 'control': control}

